//! Frozen single-proof untraced solver-phase search-participation experiment, no builds or tuning on target.
use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet},process::{Command,Stdio}};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn state()->Value{let mut out=BTreeMap::new();for p in["/proc/loadavg","/proc/swaps","/sys/fs/cgroup/cpu.max","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/memory.max","/sys/fs/cgroup/memory.events","/sys/fs/cgroup/memory.swap.max","/sys/fs/cgroup/memory.swap.events","/sys/fs/cgroup/memory.peak"]{if let Ok(s)=fs::read_to_string(p){out.insert(p,s);}}json!(out)}
fn command(name:&str,argv:Vec<String>,env:Value)->Value{json!({"kind":"command","name":name,"argv":argv,"environment":env,"timeout_seconds":900})}
fn add(dir:&Path,c:&Value,arm:&str,workers:usize,rounds:usize,panel:&str,block:usize,base:&Value)->(Value,Value,Value){let mut case=c.clone();case["workers"]=json!(workers);case["cpu_affinity"]=json!(format!("0-{}",workers-1));let name=format!("{panel}-{}-w{workers}-{arm}-b{block:02}",c["shape"].as_str().unwrap());let proof=dir.join("proofs").join(&name);let backing=block%3;let binary=format!("/usr/local/bin/{}{}",if arm=="REF"{"cr-previous"}else{"cr-current"},backing);let mut env=base.clone();env["RAYON_NUM_THREADS"]=json!(workers.to_string());env["ZOPRO_CPU_INDEXED_TILE_BUNDLES"]=json!("1");if arm!="REF"{env["ZOPRO_DIAGNOSTIC_SEARCH_DIVISOR"]=json!(if arm=="ON"{"3"}else{"0"});}let step=command(&name,vec!["/usr/bin/taskset".into(),"-c".into(),case["cpu_affinity"].as_str().unwrap().into(),binary.clone(),c["image"].as_str().unwrap().into(),c["request"].as_str().unwrap().into(),rounds.to_string(),proof.display().to_string()],env);let verify=command(&format!("verify-{name}"),vec!["/usr/local/bin/interval-verify".into(),c["image"].as_str().unwrap().into(),c["image_sha256"].as_str().unwrap().into(),proof.join("0.proof").display().to_string(),proof.join("0.public").display().to_string(),c["public_sha256"].as_str().unwrap().into()],json!({}));let job=json!({"name":name,"case":case,"arm":arm,"workers":workers,"rounds":rounds,"block":block,"panel":panel,"proof_dir":proof,"binary":binary,"backing":backing});(job,step,verify)}
fn receipt(d:&Path){let e=read(d.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for(f,k)in[("stdout.log","stdout_sha256"),("stderr.log","stderr_sha256")]{assert_eq!(hash(d.join(f)),e[k]);}}
fn main(){let phase=std::env::args().nth(1).unwrap();assert!(phase=="preflight"||phase=="measure");let dir=Path::new("/output").join(&phase);fs::create_dir(&dir).unwrap();let m=read("/cr/manifest.json");let mut pins:BTreeMap<String,String>=serde_json::from_value(m["container_pins"].clone()).unwrap();for(p,h)in &pins{assert_eq!(&hash(p),h,"{p}");}pins.insert("/cr/manifest.json".into(),hash("/cr/manifest.json"));let mut seen:BTreeSet<String>=serde_json::from_value(m["prior_proof_sha256"].clone()).unwrap();assert_eq!(seen.len(),55024);if phase=="measure"{let local=read("/cr/preflight-complete.json");assert_eq!(local["status"],"complete");assert_eq!(local["distinct_gnark_exports"],4);for h in local["new_proof_sha256"].as_array().unwrap(){assert!(seen.insert(h.as_str().unwrap().into()));}assert_eq!(seen.len(),55028);pins.insert("/cr/preflight-complete.json".into(),hash("/cr/preflight-complete.json"));let q=fs::read_to_string("/sys/fs/cgroup/cpu.max").unwrap();let q=q.split_whitespace().collect::<Vec<_>>();assert_eq!(q[0].parse::<u64>().unwrap(),96*q[1].parse::<u64>().unwrap());assert_eq!(fs::read_to_string("/sys/fs/cgroup/memory.max").unwrap().trim(),(30u64<<30).to_string());assert_eq!(fs::read_to_string("/sys/fs/cgroup/memory.swap.max").unwrap().trim(),"0");}
 let identities=backings();save(dir.join("backings-before.json"),identities.clone());save(dir.join("before.json"),state());for(name,args)in[("lscpu.txt",vec![]),("topology.csv",vec!["-p=CPU,CORE,SOCKET,ONLINE"])]{let out=Command::new("lscpu").args(args).output().unwrap();assert!(out.status.success());fs::write(dir.join(name),out.stdout).unwrap();}if phase=="measure"{let t=fs::read_to_string(dir.join("topology.csv")).unwrap();let mut cpu=BTreeSet::new();let mut cores=BTreeSet::new();for l in t.lines().filter(|l|!l.starts_with('#')){let f=l.split(',').collect::<Vec<_>>();assert_eq!(f[3],"Y");cpu.insert(f[0].parse::<usize>().unwrap());assert!(cores.insert((f[1].to_owned(),f[2].to_owned())));}assert_eq!(cpu,(0..96).collect());assert_eq!(cores.len(),96);}
 let cases=m["cases"].as_array().unwrap();assert_eq!(cases.len(),2);let primary=cases.iter().find(|c|c["shape"]=="1x2").unwrap();let mut env=m["environment"].clone();env["ZOPRO_BASIS_KEY_DIR"]="/cr-basis".into();env["ZOPRO_CPU_LAGRANGE_DIR"]="/output/lagrange-cache".into();env["ZOPRO_CPU_DEDUP"]="1".into();let mut jobs=vec![];let mut steps=vec![];
 if phase=="preflight"{for c in cases{let(j,s,v)=add(&dir,c,"ON",4,1,"preflight",0,&env);jobs.push(j);steps.extend([s,v]);}for arm in["REF","OFF"]{let(j,s,v)=add(&dir,primary,arm,4,1,"preflight",0,&env);jobs.push(j);steps.extend([s,v]);}assert_eq!(jobs.len(),4);}else{for c in cases{for w in[32,96]{for arm in["REF","OFF","ON"]{let(j,s,v)=add(&dir,c,arm,w,1,"preflight",0,&env);jobs.push(j);steps.extend([s,v]);}}}let mut verify=vec![];for block in 0..9{let mut contexts=[32,96];if block%2==1{contexts.reverse();}let mut arms=["REF","OFF","ON"];arms.rotate_left(block%3);if block%2==1{arms.reverse();}for ci in 0..2{let c=&cases[(ci+block)%2];for w in contexts{for arm in arms{let(j,s,v)=add(&dir,c,arm,w,151,"latency",block,&env);jobs.push(j);steps.push(s);verify.push(v);}}}}steps.extend(verify);assert_eq!(jobs.len(),120);}
 let requests=jobs.iter().map(|j|j["rounds"].as_u64().unwrap()+3).sum::<u64>();assert_eq!(requests,if phase=="preflight"{16}else{16680});save(dir.join("jobs.json"),json!(jobs));save(dir.join("pins.json"),json!(pins));save(dir.join("plan.json"),json!({"version":1,"source_pins":dir.join("pins.json"),"steps":steps}));let log=fs::File::create(dir.join("workflow.log")).unwrap();let status=Command::new("/usr/local/bin/cr-xtask").arg("workflow").arg(dir.join("plan.json")).arg(dir.join("workflow")).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().unwrap();assert!(status.success(),"frozen workflow failed, preserve output");
 let before=seen.clone();let mut inventory=BTreeMap::new();let mut rows=vec![];for j in &jobs{let name=j["name"].as_str().unwrap();receipt(&dir.join("workflow").join(name));receipt(&dir.join("workflow").join(format!("verify-{name}")));let proof=Path::new(j["proof_dir"].as_str().unwrap());assert_eq!(fs::metadata(proof.join("0.proof")).unwrap().len(),164);let ph=hash(proof.join("0.proof"));assert!(seen.insert(ph.clone()));let public=hash(proof.join("0.public"));assert_eq!(public,j["case"]["public_sha256"]);inventory.insert(proof.join("0.proof").display().to_string(),ph.clone());inventory.insert(proof.join("0.public").display().to_string(),public.clone());let verified=fs::read_to_string(dir.join("workflow").join(format!("verify-{name}")).join("stdout.log")).unwrap();for binding in[format!("proof_sha256={ph}"),format!("public_sha256={public}"),format!("image_sha256={}",j["case"]["image_sha256"].as_str().unwrap())]{assert!(verified.contains(&binding));}
 let text=fs::read_to_string(dir.join("workflow").join(name).join("stdout.log")).unwrap();let samples=text.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).enumerate().map(|(i,l)|{let v:Value=serde_json::from_str(l).unwrap();assert_eq!(v["round"],i);v["ns"].as_u64().unwrap_or_else(||(v["ms"].as_f64().unwrap()*1e6).round()as u64)}).collect::<Vec<_>>();assert_eq!(samples.len()as u64,j["rounds"].as_u64().unwrap());let summary:Value=serde_json::from_str(text.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["placement_before"],summary["placement_after"]);assert_eq!(summary["workers"],j["workers"]);assert_eq!(summary["indexed_entries"].as_u64().unwrap(),4*j["rounds"].as_u64().unwrap());if j["arm"]!="REF"{assert_eq!(summary["search_scopes"].as_u64().unwrap(),if j["arm"]=="ON"{j["rounds"].as_u64().unwrap()}else{0});assert_eq!(summary["search_restored"],true);}rows.push(json!({"job":j,"mean_ns":samples.iter().map(|&x|x as u128).sum::<u128>()as f64/samples.len()as f64,"usage":summary}));}
 assert_eq!(seen.len(),if phase=="preflight"{55028}else{55148});for(p,h)in &pins{assert_eq!(&hash(p),h);}save(dir.join("rows.json"),json!(rows));save(dir.join("proof-inventory.json"),json!(inventory));let after=backings();assert_eq!(identities,after);save(dir.join("backings-after.json"),after);save(dir.join("after.json"),state());save(dir.join("complete.json"),json!({"status":"complete","sdk_requests":requests,"distinct_gnark_exports":jobs.len(),"proof_ledger":seen.len(),"new_proof_sha256":seen.difference(&before).collect::<Vec<_>>(),"all_exported_proofs_independent_verified":true,"performance_requires_independent_target_gates":true}));println!("COMPLETE {}",fs::read_to_string(dir.join("complete.json")).unwrap());}

fn backings()->Value{use std::os::unix::fs::MetadataExt;let mut ids=BTreeSet::new();let mut rows=vec![];for arm in["cr-previous","cr-current"]{let mut expected=None;for i in 0..3{let p=format!("/usr/local/bin/{arm}{i}");let m=fs::metadata(&p).unwrap();assert!(ids.insert((m.dev(),m.ino())));let h=hash(&p);if let Some(e)=&expected{assert_eq!(e,&h);}else{expected=Some(h.clone());}rows.push(json!({"path":p,"dev":m.dev(),"inode":m.ino(),"sha256":h}));}}json!(rows)}
